package practice;

import java.time.LocalDate;
import java.util.List;

public final class Shipping {

    private Shipping() {
    }

    /** A kind of parcel. Other teams add kinds of their own, in their own modules. */
    public interface Parcel {
        /** Postage before any insurance, in cents. */
        long baseCents();

        /** Days from handing the parcel over to delivery. */
        int transitDays();
    }

    /** A parcel whose declared value is insured in transit. */
    public interface Insured extends Parcel {
        long declaredValueCents();
    }

    /** Letters go by post: 2 days. */
    public record Letter(int grams) implements Parcel {
        public long baseCents() {
            return 85 + (grams / 20) * 10L;
        }

        public int transitDays() {
            return 2;
        }
    }

    /** Boxes go by road: 4 days, always insured. */
    public record Box(int grams, long declaredValueCents) implements Insured {
        public long baseCents() {
            return 450 + (grams / 1000) * 120L;
        }

        public int transitDays() {
            return 4;
        }
    }

    public static final class Manifest {

        /**
         * The postage for everything on the manifest: each parcel's base postage, plus 2 % of the
         * declared value of each insured parcel, rounded up to the next cent.
         */
        long totalCents(List<? extends Parcel> parcels) {
            long total = 0;
            for (Parcel p : parcels) {
                total += p.baseCents();
                if (p instanceof Insured i) {
                    total += (i.declaredValueCents() * 2 + 99) / 100;
                }
            }
            return total;
        }

        /** The day the last parcel on the manifest is delivered, when all leave on {@code shipped}. */
        LocalDate deliveredBy(LocalDate shipped, List<? extends Parcel> parcels) {
            int days = 0;
            for (Parcel p : parcels) {
                days = Math.max(days, p.transitDays());
            }
            return shipped.plusDays(days);
        }
    }
}

package practice;

import java.time.LocalDate;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            Shipping.Manifest manifest = new Shipping.Manifest();
            List<Shipping.Parcel> van = List.of(new Shipping.Letter(70), new Shipping.Box(4_200, 8_050), new Pallet(5_500, 120_000));
            System.out.println("letter of 70 g base: " + new Shipping.Letter(70).baseCents());
            System.out.println("box of 4,200 g base: " + new Shipping.Box(4_200, 8_050).baseCents());
            System.out.println("total postage: " + manifest.totalCents(van) + " cents");
            System.out.println("delivered by: " + manifest.deliveredBy(LocalDate.of(2027, 9, 6), van));
            System.out.println("letters only, delivered by: " + manifest.deliveredBy(LocalDate.of(2027, 9, 6), List.of(new Shipping.Letter(20))));
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }

    /** A parcel kind written after Manifest: insured, eight days by rail. */
    record Pallet(long baseCents, long declaredValueCents) implements Shipping.Insured {
        public int transitDays() { return 8; }
    }
}

